{const a=affOf(S),wd=n.getUTCDay(),dn=Math.floor(Date.UTC(n.getUTCFullYear(),n.getUTCMonth(),n.getUTCDate())/864e5);for(const s of a.sch){if(s.tg===false)continue;const sl=affDue(s,m,wd);if(!sl||!await once(`a${s.id}${d}${sl}`))continue;const t=affPick(a,s,sl,dn);if(t)await say(env,chat,'✨ '+h(t))}}
